import 'package:flutter_test/flutter_test.dart';
import 'package:podx/features/price_benchmark/domain/price_benchmark_models.dart';
import 'package:podx/features/price_benchmark/domain/price_benchmark_services.dart';

void main(){
  group('effective price',(){const calculator=EffectivePriceCalculator(); test('includes offer, delivery, platform and other charges',(){final listing=OnlinePriceListing(id:'1',source:const OnlinePriceSource(id:'s',name:'Online Store A',type:OnlineSourceType.mock),productId:'p',listedPrice:100,offerPrice:90,deliveryFee:10,platformFee:3,otherCharges:2,minimumOrderValue:0,available:true,quantity:1,unit:'kg',variant:'plain',lastCheckedAt:DateTime(2026)); expect(calculator.online(listing).total,105);}); test('keeps optional local travel separate by default',(){expect(calculator.local(sellingPrice:100,offerPrice:95,travelCost:10).total,95);expect(calculator.local(sellingPrice:100,offerPrice:95,travelCost:10,includeOptionalCosts:true).total,105);});});
  test('savings amount and percentage use lowest effective online price',(){const b=PriceBenchmark(localLowest:95,localAverage:100,localHighest:105,onlineLowest:112,onlineAverage:120,onlineHighest:125,overallAverage:109,median:108,fairRange:FairPriceRange(95,120),observations:6,volatility:4,freshness:DataFreshness.updatedToday);expect(b.savingsAmount,17);expect(b.savingsPercentage,closeTo(15.178,0.01));});
  test('unit prices normalize grams',(){final u=const UnitPriceCalculator().calculate(price:95,quantity:500,unit:'g')!;expect(u.amount,19);expect(u.basis,100);});
  test('pack mismatch is not exact product match',(){final r=const ProductMatchingService().match(localBrand:'A',onlineBrand:'A',localProduct:'Rice',onlineProduct:'Rice',localQuantity:1,onlineQuantity:2,localUnit:'kg',onlineUnit:'kg',localVariant:'white',onlineVariant:'white');expect(r.matches,isFalse);expect(r.packSizeMatch,PackSizeMatch.equivalentUnit);});
  test('freshness boundaries classify stale and expired',(){final now=DateTime(2026,7,27);expect(priceFreshness(now.subtract(const Duration(days:8)),now),DataFreshness.stale);expect(priceFreshness(now.subtract(const Duration(days:15)),now),DataFreshness.expired);});
  test('low confidence suppresses comparison labels',(){final c=const PriceConfidenceService().calculate(localListings:1,onlineObservations:1,matchConfidence:.4,packSizeMatch:PackSizeMatch.mismatch,freshness:DataFreshness.stale,consistency:.4,sourceReliability:.3);expect(c.level,PriceConfidenceLevel.low);expect(c.canShowComparisonLabel,isFalse);});
  test('seller price position is neutral and deterministic',(){expect(sellerPricePosition(sellerPrice:100,localLowest:90,localAverage:101),SellerPricePosition.nearAverage);});
  test('comparison alerts meet threshold and prevent duplicates',(){final service=PriceComparisonAlertService();expect(service.evaluate(productId:'p',localPrice:95,onlineEffectivePrice:112,minimumPercent:10),isNotNull);expect(service.evaluate(productId:'p',localPrice:95,onlineEffectivePrice:112,minimumPercent:10),isNull);});
  test('stale data suppresses strong savings insight',(){final insight=const PriceInsightService().create(localLowest:90,onlineLowest:120,freshness:DataFreshness.stale);expect(insight.type,PriceInsightType.stale);expect(insight.strongClaimAllowed,isFalse);});
  test('no-data states are explicit',(){expect(const PriceInsightService().create(localLowest:90,onlineLowest:null,freshness:DataFreshness.updatedToday).type,PriceInsightType.onlineUnavailable);expect(const PriceInsightService().create(localLowest:null,onlineLowest:90,freshness:DataFreshness.updatedToday).type,PriceInsightType.localUnavailable);});
}
